from app.domain import Card
from app.abilities import CardRepository


class InMemoryCardRepository(CardRepository):
    def __init__(self, cards: tuple[Card, ...] = ()):
        self.cards = {card.id: card for card in cards}
        self.saved_cards: list[Card] = []

    def get_card(self, card_id: str) -> Card | None:
        return self.cards.get(card_id)

    def list_cards(self) -> tuple[Card, ...]:
        return tuple(self.cards.values())

    def save_card(self, card: Card) -> None:
        self.cards[card.id] = card
        self.saved_cards.append(card)
